(()=>{'use strict';
 async function image(file){const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('图片无法读取，请另存为 JPG 或 PNG。'));im.src=url;});const scale=Math.min(1,1600/img.naturalWidth,1600/img.naturalHeight),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return {name:file.name,image:canvas.toDataURL('image/jpeg',.78),size:file.size,warnings:['图片会交给当前模型，需模型支持图片理解。']};}finally{URL.revokeObjectURL(url);}}
 async function pdf(file){let library;try{library=await import('./vendor/pdf.min.mjs');}catch{throw new Error('此系统无法加载 PDF 解析器，可将内容另存为文本或图片。');}library.GlobalWorkerOptions.workerSrc=new URL('vendor/pdf.worker.min.mjs',location.href).href;let doc;try{doc=await library.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,disableFontFace:true,useSystemFonts:true}).promise;let text='',truncated=doc.numPages>80;for(let i=1;i<=Math.min(doc.numPages,80);i++){const page=await doc.getPage(i),content=await page.getTextContent();text+='〔第 '+i+' 页〕\n'+content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('')+'\n';page.cleanup();if(text.length>32000){truncated=true;break;}}if(!text.replace(/〔第 \d+ 页〕/g,'').trim())throw new Error('PDF 没有可复制文字，可将扫描页另存为图片后添加。');return {name:file.name,size:file.size,text:text.slice(0,32000),truncated,warnings:['提取 PDF 文字，不保证扫描页和图表完整。']};}finally{await doc?.destroy();}}
 async function read(file){if(file.size>20*1024*1024)throw new Error('单个文件最多20MB。');if(!file.size)throw new Error('这是空文件。');if(/\.(png|jpe?g|webp|gif|heic|heif)$/i.test(file.name)||file.type.startsWith('image/'))return image(file);if(/\.pdf$/i.test(file.name))return pdf(file);return await new Promise(async(resolve,reject)=>{const worker=new Worker('file-worker.js'),timer=setTimeout(()=>{worker.terminate();reject(new Error('文件读取超时，请拆分后重试。'));},30000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();e.data.ok?resolve({...e.data.result,size:file.size}):reject(new Error(e.data.error));};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(new Error('文件解析器不可用。'));};try{const buffer=await file.arrayBuffer();worker.postMessage({buffer,name:file.name},[buffer]);}catch(e){clearTimeout(timer);worker.terminate();reject(e);}});}
 window.FishbotReadFile=read;
})();
